// topic: mf/v1/site/{site}/asset/{asset}/{type}
const p = msg.topic.split('/');
if (p.length !== 7 || p[0] !== 'mf' || p[1] !== 'v1' || p[2] !== 'site' || p[4] !== 'asset') {
    node.warn(`ignored topic ${msg.topic}`);
    return null;
}
const [site, asset, type] = [p[3], p[5], p[6]];
if (type === 'command') return null;                  // our own outbound commands
if (!['telemetry', 'status', 'event'].includes(type)) {
    node.warn(`unknown message type '${type}' on ${msg.topic}`);
    return null;
}
let body;
try { body = JSON.parse(msg.payload); }
catch (e) { node.warn(`invalid JSON on ${msg.topic}`); return null; }
if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    node.warn(`payload must be a JSON object on ${msg.topic}`); return null;
}
msg.mf = { site, asset, type };
msg.query = 'SELECT mf.ingest($1, $2, $3, $4::jsonb) AS result';
msg.params = [site, asset, type, JSON.stringify(body)];
return msg;

const r = msg.payload && msg.payload[0] && msg.payload[0].result;
if (!r) return null;
if (!r.ok) {
    node.warn({ rejected: r, topic: msg.topic });
    return [null, null, { payload: r, topic: msg.topic }];
}
const done = r.order_completed;
if (!done) return null;

// 1) tell the machine the order is finished
const cmd = {
    topic: `mf/v1/site/${done.site}/asset/${done.asset}/command`,
    payload: { command: 'complete_order', order_number: done.order_number }
};
// 2) send the production receipt back to the (demo) ERP
const receipt = {
    method: 'POST',
    url: 'http://127.0.0.1:1880/demo-erp/receipts',
    headers: { 'content-type': 'application/json',
               authorization: 'Bearer ' + env.get('MF_API_TOKEN') },
    payload: done
};
node.status({ fill: 'green', shape: 'dot', text: `${done.order_number} complete` });
return [cmd, receipt, null];

