const b = msg.payload || {};
const asset = b.asset || b.asset_id;
const qty = Number(b.target_quantity);
if (!asset || !b.order_number) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'asset and order_number are required' }; return [null, msg, null]; }
if (!Number.isInteger(qty) || qty <= 0 || qty > 1000000) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'target_quantity must be a positive integer' }; return [null, msg, null]; }
msg.route = 'create_order';
msg.query = 'SELECT mf.create_order($1, $2, $3, $4, $5, $6) AS result';
msg.params = [String(b.site || 'demo'), String(asset), String(b.order_number),
              b.part_number ? String(b.part_number) : null, qty, String(b.source_system || 'API')];
return [msg, null, null];

if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return [null, msg, null];
}

const b = (msg.payload && typeof msg.payload === 'object') ? { ...msg.payload } : null;
if (!b) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'JSON object body required' }; return [null, msg, null]; }
const asset = b.asset || b.asset_id;
const site = String(b.site || 'demo');
if (!asset || !/^[A-Za-z0-9_.-]+$/.test(asset) || !/^[A-Za-z0-9_.-]+$/.test(site))
    { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'valid asset (and optional site) required' }; return [null, msg, null]; }
const TYPE = 'telemetry';
if (TYPE === 'telemetry' && (typeof b.signals !== 'object' || b.signals === null)) {
    // accept flat bodies: { asset_id, temperature: 186.4, pressure: 1840 }
    const signals = {};
    for (const [k, v] of Object.entries(b)) {
        if (!['site', 'asset', 'asset_id', 'timestamp', 'units'].includes(k)) signals[k] = v;
    }
    b.signals = signals;
}
if (TYPE === 'event' && !b.event_type) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'event_type required' }; return [null, msg, null]; }
if (TYPE === 'status' && !b.status) { msg.statusCode = 400; msg.payload = { error: 'bad_request', detail: 'status required' }; return [null, msg, null]; }
b.timestamp = b.timestamp || new Date().toISOString();
const pub = { topic: `mf/v1/site/${site}/asset/${asset}/${TYPE}`, payload: JSON.stringify(b) };
msg.statusCode = 202;
msg.payload = { accepted: true, topic: pub.topic };
return [null, msg, pub];

