const row = (msg.payload && msg.payload[0]) || {};
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

if (msg.route === 'health') {
    msg.statusCode = 200;
    msg.payload = { status: 'ok', service: 'manufaction', version: env.get('MF_VERSION') || '0.1.0',
                    db_time: row.db_time };
    return [msg, null];
}
if (msg.route === 'data') {
    if (row.data === null || row.data === undefined) {
        msg.statusCode = 404; msg.payload = { error: 'not_found' };
    } else {
        msg.statusCode = 200; msg.payload = row.data;
    }
    return [msg, null];
}
if (msg.route === 'create_order') {
    const r = row.result || { ok: false, status_code: 500, error: 'no_result' };
    msg.statusCode = r.status_code || (r.ok ? 201 : 400);
    msg.payload = r.ok ? r.order : { error: r.error, detail: r.detail };
    if (!r.ok) return [msg, null];
    const o = r.order;
    const cmd = {
        topic: `mf/v1/site/${o.site}/asset/${o.asset}/command`,
        payload: { command: 'start_order', order_number: o.order_number,
                   part_number: o.part_number, target_quantity: o.target_quantity }
    };
    return [msg, cmd];
}
msg.statusCode = 500; msg.payload = { error: 'unknown_route' };
return [msg, null];

if (!msg.res) return null;
msg.statusCode = msg.route === 'health' ? 503 : 500;
msg.headers = { 'content-type': 'application/json' };
msg.payload = { error: msg.route === 'health' ? 'database_unavailable' : 'internal_error' };
node.warn(msg.error && msg.error.message);
return msg;

msg.query = 'SELECT * FROM mf.pending_dispatch()';
msg.params = [];
return msg;

const rows = msg.payload || [];
node.status({ text: `${rows.length} dispatched @ ${new Date().toLocaleTimeString()}` });
return [rows.map(o => ({
    topic: `mf/v1/site/${o.site_code}/asset/${o.asset_code}/command`,
    payload: { command: 'start_order', order_number: o.order_number,
               part_number: o.part_number, target_quantity: o.target_quantity }
}))];

msg.query = 'SELECT mf.purge_telemetry($1) AS deleted';
msg.params = [Number(env.get('MF_TELEMETRY_KEEP_DAYS') || 7)];
return msg;

if (env.get('DEMO_ERP_ENABLED') === 'false') return null;
msg.query = 'SELECT * FROM demo_erp.assets_needing_orders()';
msg.params = [];
return msg;

const SIZE = { 'PRESS-001': [30, 60], 'CNC-001': [8, 16], 'ASSEMBLY-001': [12, 24],
    'PRESS-002': [25, 50], 'CNC-002': [6, 12], 'ASSEMBLY-002': [10, 20] };
const d = new Date();
const stamp = d.toISOString().slice(2, 10).replace(/-/g, '');
return [(msg.payload || []).map(a => {
    const [lo, hi] = SIZE[a.asset_code] || [10, 20];
    const order = {
        site: a.site_code, asset: a.asset_code, part_number: a.part_number,
        order_number: `MO-${stamp}-${Math.floor(Math.random() * 9000 + 1000)}`,
        target_quantity: Math.floor(Math.random() * (hi - lo + 1)) + lo,
        source_system: 'DEMO-ERP'
    };
    return {
        method: 'POST', url: 'http://127.0.0.1:1880/api/v1/production-orders',
        headers: { 'content-type': 'application/json', authorization: 'Bearer ' + env.get('MF_API_TOKEN') },
        payload: order
    };
})];

if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401;
    msg.payload = { error: 'unauthorized' };
    return [null, msg, null];
}

msg.query = 'SELECT demo_erp.record_receipt($1::jsonb) AS result';
msg.params = [JSON.stringify(msg.payload || {})];
return [msg, null, null];

msg.statusCode = 201;
msg.payload = msg.payload[0].result;
node.status({ fill: 'blue', shape: 'dot', text: `receipt ${msg.payload.receipt_id}` });
return msg;

if (!msg.res) { node.warn(msg.error && msg.error.message); return null; }
msg.statusCode = 500; msg.payload = { error: 'internal_error' };
return msg;

if (!env.get('MF_NOTIFY_WEBHOOK_URL')) { node.status({ fill: 'grey', shape: 'ring', text: 'disabled (no MF_NOTIFY_WEBHOOK_URL)' }); return null; }
node.status({ fill: 'green', shape: 'dot', text: 'enabled' });
msg.query = 'SELECT * FROM mf.pending_deliveries(10)';
msg.params = [];
return msg;

const url = env.get('MF_NOTIFY_WEBHOOK_URL');
const fmt = (env.get('MF_NOTIFY_FORMAT') || 'json').toLowerCase();
const token = env.get('MF_NOTIFY_BEARER_TOKEN');
const oneLine = s => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ');

return [(msg.payload || []).map(r => {
    const m = { notification_id: r.id, method: 'POST', url, headers: {} };
    if (token) m.headers.authorization = 'Bearer ' + token;
    if (fmt === 'slack') {                    // Slack / Mattermost incoming webhook
        m.headers['content-type'] = 'application/json';
        m.payload = { text: r.text };
    } else if (fmt === 'discord') {
        m.headers['content-type'] = 'application/json';
        m.payload = { content: r.text };
    } else if (fmt === 'text') {              // ntfy.sh and similar: plain-text body
        m.headers['content-type'] = 'text/plain; charset=utf-8';
        m.headers.title = oneLine(r.title);
        m.payload = r.text;
    } else {                                  // json: full event, for Zapier / Make / your own endpoint
        m.headers['content-type'] = 'application/json';
        m.payload = {
            source: 'manufaction', event: r.kind, severity: r.severity, site: r.site_code,
            asset: r.asset_code, title: r.title, message: r.text,
            work_request: r.work_request, reason_code: r.reason_code, occurred_at: r.created_at
        };
    }
    return m;
})];

const ok = msg.statusCode >= 200 && msg.statusCode < 300;
if (!ok) node.warn('webhook returned HTTP ' + msg.statusCode + ' for notification ' + msg.notification_id);
msg.query = 'SELECT mf.mark_delivery($1, $2, $3)';
msg.params = [msg.notification_id, ok, ok ? null : 'HTTP ' + msg.statusCode];
return msg;

if (msg.notification_id == null) return null;
// connection-level failure (DNS, refused, timeout). Keep the message short: never log the URL.
const why = String((msg.error && msg.error.message) || 'request failed').replace(/https?:\/\/\S+/g, '[url]').slice(0, 150);
node.warn('webhook send failed for notification ' + msg.notification_id + ': ' + why);
msg.query = 'SELECT mf.mark_delivery($1, false, $2)';
msg.params = [msg.notification_id, why];
return msg;
